putEvent(key: string, payload: unknown): Event {
  const existing = this.events.get(key);
  if (existing) return structuredClone(existing);

  const event = { key, payload: structuredClone(payload), sequence: this.events.size + 1 };
  this.events.set(key, event);
  return structuredClone(event);
}

import test from "node:test";
import assert from "node:assert/strict";
import { Repository } from "../src/repository.ts";

test("first event wins and only new keys receive sequence numbers", () => {
  const repository = new Repository();
  const first = repository.putEvent("a", { value: "original" });
  const second = repository.putEvent("b", null);

  assert.deepEqual(repository.putEvent("a", { value: "replacement" }), first);
  assert.deepEqual(repository.putEvent("b", { value: "replacement" }), second);
  // A duplicate payload is ignored even when it cannot be cloned.
  assert.deepEqual(repository.putEvent("a", () => {}), first);
  const third = repository.putEvent("c", { value: "third" });

  assert.deepEqual([first.sequence, second.sequence, third.sequence], [1, 2, 3]);
  assert.deepEqual([...repository.events.values()], [first, second, third]);
});

test("input payloads and returned events are isolated from stored events", () => {
  const repository = new Repository();
  const payload = { nested: { values: [1] } };
  const expected = { key: "a", payload: structuredClone(payload), sequence: 1 };
  const first = repository.putEvent("a", payload);

  payload.nested.values.push(2);
  first.payload.nested.values.push(3);
  first.key = "changed";
  first.sequence = 99;
  assert.deepEqual(repository.events.get("a"), expected);

  const duplicate = repository.putEvent("a", { ignored: true });
  assert.deepEqual(duplicate, expected);
  duplicate.payload.nested.values.push(4);
  duplicate.sequence = 100;
  assert.deepEqual(repository.putEvent("a", undefined), expected);
  assert.deepEqual(repository.events.get("a"), expected);
});
